                              const mgAvg = mc > 0 ? Math.round(mg / mc) : 0
                              const msAvg = mc > 0 ? Math.round(ms / mc) : 0
                              return (
                                <div key={s.seller_email} className="la-drill-seller-row" style={{ paddingLeft: '40px' }} onClick={() => setDrillSeller(s)}>
