                                  <div style={{ display: 'flex', gap: '10px' }}>
                                    <span style={{ color: '#3B82F6' }}>{mgAvg}%</span>
                                    <span style={{ color: '#EAB308' }}>{msAvg}%</span>
                                  </div>
                                </div>
